package com.example.crm.sales; import org.springframework.stereotype.Service; import java.util.*; import java.math.BigDecimal;
@Service public class DealService {final DealRepository repo;final DealMapper mapper; public DealService(DealRepository r,DealMapper m){repo=r;mapper=m;} public List<DealDto> all(){return repo.findAll().stream().map(mapper::toDto).toList();} public DealDto one(UUID id){return repo.findById(id).map(mapper::toDto).orElseThrow();} public DealDto create(String t,BigDecimal a,UUID c){return mapper.toDto(repo.save(mapper.toEntity(t,a,c)));} public DealDto update(UUID id,String t,BigDecimal a,UUID c){var d=repo.findById(id).orElseThrow();mapper.update(d,t,a,c);return mapper.toDto(repo.save(d));} public DealDto stage(UUID id,Deal.Stage s){var d=repo.findById(id).orElseThrow();d.setStage(s);return mapper.toDto(repo.save(d));} public void delete(UUID id){if(!repo.existsById(id))throw new NoSuchElementException();repo.deleteById(id);} }
